// Converts the sidebar docusaurus-plugin-openapi-docs generates for the
// Management API into a committed CommonJS module that api-sidebar.js can
// require, and tidies it for use as navigation.
//
// Why a conversion step rather than requiring the generated file directly:
// the plugin emits TypeScript (`api/management/sidebar.ts`), this repo has no
// TypeScript toolchain, and `api-sidebar.js` is CommonJS -- so the generated
// file cannot be required as-is.
//
// Two tidies applied on the way through, both cosmetic and both about the
// generated labels being wrong for a nav rather than wrong in the spec:
//
//   * Category labels come from the OpenAPI tag name, which is lowercase and
//     kebab-cased by convention ("ip-rules"). That is correct in the spec and
//     poor in a sidebar, so TAG_LABELS maps each to display case. A tag with
//     no mapping falls back to a de-kebabed, capitalised form, so adding a tag
//     upstream degrades gracefully instead of breaking the build.
//   * Endpoint labels come from the operation summary, which is a sentence and
//     ends in a period. Trailing periods are dropped to match the hand-written
//     Extensions API sidebar.
//
// Run via `pnpm gen-api-mgmt-sidebar` (included in `regen-api-docs`).

import { readFileSync, writeFileSync, rmSync } from "node:fs";

const SRC = "api/management/sidebar.ts";
const OUT = "api/management/sidebar.js";

const TAG_LABELS = {
  orgs: "Organizations",
  billing: "Billing",
  clusters: "Clusters",
  deployments: "Deployments",
  "customer-domains": "Custom Domains",
  // Deliberately not just "Extensions": in the Management API an extension is a
  // custom jar or theme uploaded to a cluster, whereas the neighbouring
  // Extensions API means Phase Two's own additions to Keycloak. Same word, two
  // meanings, adjacent in the same sidebar.
  extensions: "Cluster Extensions",
  "environment-variables": "Environment Variables",
  "ip-rules": "IP Rules",
  logs: "Logs",
};

const titleCase = (tag) =>
  tag
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");

let src;
try {
  src = readFileSync(SRC, "utf8");
} catch {
  console.error(
    `${SRC} not found. Run \`pnpm gen-api-docs\` (or \`docusaurus gen-api-docs management\`) first.`,
  );
  process.exit(1);
}

// Turn the generated TS module into something evaluable without a TS toolchain.
const body = src
  .replace(/^import type .*$/m, "")
  .replace("const sidebar: SidebarsConfig =", "const sidebar =")
  .replace(
    /export default sidebar\.apisidebar;\s*$/,
    "return sidebar.apisidebar;",
  );

const items = new Function(body)();

let categories = 0;
let relabelled = 0;
for (const entry of items) {
  if (entry.type !== "category") continue;
  categories++;
  const tag = entry.label;
  entry.label = TAG_LABELS[tag] ?? titleCase(tag);
  if (!(tag in TAG_LABELS)) {
    console.warn(
      `  note: tag "${tag}" has no entry in TAG_LABELS; using "${entry.label}"`,
    );
  }
  for (const item of entry.items ?? []) {
    if (typeof item.label === "string" && item.label.endsWith(".")) {
      item.label = item.label.slice(0, -1);
      relabelled++;
    }
  }
}

// The plugin writes each category's landing page as `<tag>.tag.mdx` with the
// raw tag as both title and description ("ip-rules"), which reads badly as a
// page heading. Restate them from the spec's own tag descriptions.
const spec = JSON.parse(readFileSync("static/openapi-management.json", "utf8"));
const tagDescriptions = Object.fromEntries(
  (spec.tags ?? []).map((t) => [t.name, t.description]),
);

let tagPages = 0;
for (const tag of Object.keys(tagDescriptions)) {
  const file = `api/management/${tag}.tag.mdx`;
  let page;
  try {
    page = readFileSync(file, "utf8");
  } catch {
    continue; // a declared tag with no operations produces no page
  }
  const label = TAG_LABELS[tag] ?? titleCase(tag);
  const description = tagDescriptions[tag] ?? label;
  writeFileSync(
    file,
    page
      .replace(/^title: .*$/m, `title: "${label}"`)
      .replace(
        /^description: .*$/m,
        `description: "${description.replace(/"/g, '\\"')}"`,
      ),
  );
  tagPages++;
}

const header = `// GENERATED by scripts/gen-management-sidebar.mjs from the OpenAPI spec.
// Do not edit by hand -- run \`pnpm regen-api-docs\`.
`;
writeFileSync(
  OUT,
  `${header}module.exports = ${JSON.stringify(items, null, 2)};\n`,
);
rmSync(SRC, { force: true });

console.log(
  `Wrote ${OUT}: ${categories} categories, ${relabelled} endpoint labels ` +
    `de-punctuated, ${tagPages} tag landing pages retitled.`,
);
